// Official Barlow Semi Condensed (Google Fonts revision 89f5431ff0db41bd2fe3f7ba21a723a01622428b), OFL.
// Full glyph sets from the same TTFs used by the native overlay, converted losslessly to WOFF2.
// The corresponding OFL license is packaged in assets/fonts/OFL.txt.
const webFontCSS = `
@font-face{font-family:ClawPreviewBarlow;src:url(data:font/woff2;base64,) format("woff2");font-style:normal;font-weight:300;font-display:block}
@font-face{font-family:ClawPreviewBarlow;src:url(data:font/woff2;base64,) format("woff2");font-style:normal;font-weight:400;font-display:block}
@font-face{font-family:ClawPreviewBarlow;src:url(data:font/woff2;base64,) format("woff2");font-style:normal;font-weight:600;font-display:block}
@font-face{font-family:ClawPreviewBarlow;src:url(data:font/woff2;base64,) format("woff2");font-style:normal;font-weight:700;font-display:block}
@font-face{font-family:ClawPreviewSans;src:url(data:font/woff2;base64,) format("woff2");font-style:normal;font-weight:400;font-display:block}
`;

// ImGui/STB uses font ascent minus descent for SizePixels, while CSS uses the
// em square. Keep the line box/pixel padding unchanged and scale glyphs only.
export const previewFontCSS = webFontCSS.replace(/@font-face\{[^}]+\}/g,face=>
 face.replace('font-display:block',`font-display:block;size-adjust:${face.includes('ClawPreviewBarlow')?1000/1200*100:2048/2384*100}%`));
